"""Verify OpenAI GPT-5.1 and retained Ollama selection without model calls."""

from collections.abc import AsyncIterator
from pathlib import Path
from unittest.mock import AsyncMock, Mock

import pytest

from app.core.config import Settings, load_yaml_config, merge_llm_from_env
from app.core.llm import LiteLLMProvider


@pytest.mark.asyncio
@pytest.mark.parametrize("streaming", [False, True])
async def test_gpt51_requests(monkeypatch: pytest.MonkeyPatch, streaming: bool) -> None:
    """Verify configured GPT-5.1 reaches LiteLLM in both generation modes."""
    monkeypatch.delenv("LLM_PROVIDER", raising=False)
    monkeypatch.delenv("LLM_MODEL", raising=False)
    config = load_yaml_config(Path(__file__).resolve().parents[2] / "config.yaml")
    settings = Settings(_env_file=None, OPENAI_API_KEY="test-key-not-real")
    merged = merge_llm_from_env(config, settings)
    assert (merged.provider, merged.model) == ("openai", "gpt-5.1")

    async def tokens() -> AsyncIterator[Mock]:
        """Return synthetic streaming content without external model calls."""
        yield Mock(choices=[Mock(delta=Mock(content="Test answer"))])

    response = tokens() if streaming else Mock(choices=[Mock(message=Mock(content="Test answer"))])
    completion = AsyncMock(return_value=response)
    monkeypatch.setattr("app.core.llm.litellm.acompletion", completion)
    monkeypatch.setattr("app.core.llm.litellm.api_key", None)
    provider = LiteLLMProvider(merged, settings)
    messages = [{"role": "user", "content": "Test question"}]
    answer = (
        "".join([part async for part in provider.astream(messages)])
        if streaming else await provider.acomplete(messages)
    )
    assert answer == "Test answer"
    assert completion.call_args.kwargs["model"] == "gpt-5.1"
    assert completion.call_args.kwargs["stream"] is streaming
    assert completion.call_args.kwargs["messages"] == messages


def test_ollama_environment_override(monkeypatch: pytest.MonkeyPatch) -> None:
    """Keep local generation available when its provider and model are selected."""
    monkeypatch.setenv("LLM_PROVIDER", "ollama_chat")
    monkeypatch.setenv("LLM_MODEL", "qwen2.5:1.5b")
    config = load_yaml_config(Path(__file__).resolve().parents[2] / "config.yaml")
    settings = Settings(_env_file=None, OPENAI_API_KEY="")
    provider = LiteLLMProvider(merge_llm_from_env(config, settings), settings)
    assert provider._model() == "ollama_chat/qwen2.5:1.5b"
